Copy the workbook, read cached values from the active sheet, and sum the five Points columns (F, H, J, L, N) for rows 4–7, using the Place mapping as a fallback if a point cell is blank. Write the numeric row totals into O4:O7 as plain values. Save the output workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = vals.active.title if vals.active is not None else None
if sheet_name is None or sheet_name not in wb.sheetnames:
    sheet_name = "SANDBOX" if "SANDBOX" in wb.sheetnames else wb.active.title

ws_vals = vals[sheet_name]
ws = wb[sheet_name]

# Points columns for Events 1-5: F, H, J, L, N
point_cols = [6, 8, 10, 12, 14]
# Corresponding Place columns: E, G, I, K, M
place_cols = [5, 7, 9, 11, 13]

place_to_points = {
    "1st": 3,
    "2nd": 2,
    "3rd": 1,
    "CH": 5,
    "RCH": 4,
}

def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == "")

def to_num(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if s in ("", "-"):
            return 0.0
        try:
            return float(s)
        except ValueError:
            return 0.0
    return 0.0

for r in range(4, 8):
    total = 0.0
    row_has_data = False

    for pc, sc in zip(place_cols, point_cols):
        place_val = ws_vals.cell(row=r, column=pc).value
        point_val = ws_vals.cell(row=r, column=sc).value

        if not is_blank(place_val) or not is_blank(point_val):
            row_has_data = True

        pts = to_num(point_val)

        # Fallback: if the point cell is empty/zero but the place cell has a known result,
        # compute the point value from the place text.
        if pts == 0.0 and isinstance(place_val, str):
            key = place_val.strip()
            if key in place_to_points:
                pts = float(place_to_points[key])

        total += pts

    if not row_has_data:
        out_val = None
    else:
        out_val = int(total) if float(total).is_integer() else round(total, 2)

    ws.cell(row=r, column=15).value = out_val  # Column O
    print(f"Row {r}: O{r} = {out_val}")

wb.save(OUT)
